Assume the usual includes.

struct Storage { int id; };
struct Reader : Storage { };
struct Writer : Storage { };
struct ReadWriter : Reader, Writer { void set() { id = 5; } };

What happens at the line id = 5;, and what is the standard remedy?

Assuming the usual includes and using namespace std, what does this program print?

struct B { virtual void f(int n = 1) { cout << "B" << n; } };
struct D : B { void f(int n = 2) override { cout << "D" << n; } };
int main() { B* p = new D; p->f(); }

Assuming the usual includes and using namespace std, what does this program print?

struct B { B() { speak(); } virtual void speak() { cout << "B"; } };
struct D : B { void speak() override { cout << "D"; } };
int main() { D d; }

Assume the usual includes and using namespace std. The file nums.txt contains the three numbers 10 20 30 separated by single spaces and followed by one newline. How many times does the body of this loop execute?

ifstream in("nums.txt");
int x, count = 0;
while (!in.eof()) { in >> x; ++count; }
cout << count;

The file data.bin is exactly 40 bytes long. Assume the usual includes and using namespace std. What does this fragment print?

ifstream f("data.bin", ios::binary);
char buf[100];
f.read(buf, 100);
cout << f.gcount();

Assuming the usual includes and using namespace std, what does this program print?

struct T { const char* n; ~T() { cout << n; } };
void f() { T a{"a"}; throw 1; T b{"b"}; }
int main() {
  try { T c{"c"}; f(); } catch (int) { cout << "X"; }
}

